package com.jnapanam.sportszone.notification.provider;
import com.jnapanam.sportszone.notification.model.*;import com.jnapanam.sportszone.notification.service.NotificationProviderSettingsService;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class GenericHttpNotificationProvider implements NotificationProvider{private final RestClient http=RestClient.create();private final String url,token;private final NotificationProviderSettingsService settings;public GenericHttpNotificationProvider(NotificationProviderSettingsService settings,@Value("${app.notification.whatsapp.provider-url:}")String url,@Value("${app.notification.whatsapp.provider-token:}")String token){this.settings=settings;this.url=url;this.token=token;}public NotificationChannel channel(){return NotificationChannel.WHATSAPP;}public String name(){return "generic-http";}public String send(Notification n){String activeUrl=settings.value("WHATSAPP_PROVIDER_URL",url),activeToken=settings.value("WHATSAPP_PROVIDER_TOKEN",token);if(activeUrl==null||activeUrl.isBlank())throw new IllegalStateException("WhatsApp provider is not configured");Map<String,Object> body=Map.of("destination",Optional.ofNullable(n.getUser().getMobile()).orElse(""),"subject",Optional.ofNullable(n.getSubject()).orElse(""),"message",n.getMessage());Map response=http.post().uri(activeUrl).header(HttpHeaders.AUTHORIZATION,"Bearer "+activeToken).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Map.class);return response!=null&&response.get("id")!=null?response.get("id").toString():"whatsapp-"+n.getId();}}
